import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadValleyData(){const e=readFileSync(resolve(__dirname,"../../frontend/valley-of-flowers-explorer/valley-data.js"),"utf-8");return new Function(e+"\nreturn { VALLEY_INFO, ECOLOGY_HYDROLOGY, FLORA_FAUNA_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadNationalParksLandingData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn NATIONAL_PARKS;")()}describe("Valley of Flowers National Park Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadValleyData()}),describe("VALLEY_INFO metadata",()=>{it("contains correct park metadata and UNESCO status",()=>{expect(e.VALLEY_INFO.id).toBe("valley-of-flowers"),expect(e.VALLEY_INFO.name).toContain("Valley of Flowers"),expect(e.VALLEY_INFO.unescoYear).toBe(2005),expect(e.VALLEY_INFO.state).toBe("Uttarakhand")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.VALLEY_INFO.quickStats)).toBe(!0),expect(e.VALLEY_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, Pushpawati river hydrology, history, and status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.history).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("FLORA_FAUNA_SPECIES catalog",()=>{it("is a non-empty array of alpine flora and fauna species",()=>{expect(Array.isArray(e.FLORA_FAUNA_SPECIES)).toBe(!0),expect(e.FLORA_FAUNA_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Himalayan Blue Poppy and Snow Leopard",()=>{const t=e.FLORA_FAUNA_SPECIES.find(e=>"blue-poppy"===e.id),a=e.FLORA_FAUNA_SPECIES.find(e=>"snow-leopard"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in NATIONAL_PARKS_DATA landing page dataset",()=>{const e=loadNationalParksLandingData().find(e=>"valley-of-flowers"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../valley-of-flowers-explorer/index.html")})})});